//! Canonical FORM boolean metadata connects to native submission validation.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=form novalidate=legacy method=post action=https://form-no-validate.test/submit><input id=area name=q required><input id=other type=checkbox name=check required></form><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://form-no-validate.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn form_no_validate_canonical_boolean_accessor_and_presence(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form'),a=Object.getOwnPropertyDescriptor(HTMLFormElement.prototype,'noValidate');if(!a||!a.enumerable||!a.configurable||a.get.length!==0||a.set.length!==1||a.get.name!=='get noValidate'||a.set.name!=='set noValidate'||Object.hasOwn(x,'noValidate')||x.noValidate!==true||x.getAttributeNS(null,'novalidate')!=='legacy')throw 'canonical boolean';");}
#[test]
fn form_no_validate_hook_free_boolean_attr_identity_and_observation(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form'),old=x.getAttributeNodeNS(null,'novalidate'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.noValidate=false;var records=watch.takeRecords();if(x.noValidate!==false||old.ownerElement!==null||old.value!=='legacy'||records.length!==1||records[0].oldValue!=='legacy'||records[0].attributeName!=='novalidate')throw 'remove';var calls=0;x.noValidate={toString:function(){calls++;throw 'conversion';},valueOf:function(){calls++;throw 'conversion';}};records=watch.takeRecords();if(calls||x.noValidate!==true||x.getAttributeNS(null,'novalidate')!==''||records.length!==1||records[0].oldValue!==null||document.getElementById('neighbor').value!=='seed')throw 'hook free bool';");}
#[test]
fn form_no_validate_toggles_native_required_submission_without_changing_controls(){let(mut d,mut f,mut p)=fixture();let owner=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("form")).unwrap();let loc=crate::navigation::address("https://form-no-validate.test/source",&crate::navigation::Location::home()).unwrap();let before=f.controls.iter().map(|(&n,c)|(n,c.required,c.checked,c.value.text(),c.owner)).collect::<Vec<_>>();assert!(f.submit_request(&d,owner,None,&loc,&loc).is_ok());run(&mut d,&mut f,&mut p,"var x=document.getElementById('form');x.noValidate=false;");assert!(f.submit_request(&d,owner,None,&loc,&loc).is_err());run(&mut d,&mut f,&mut p,"x.noValidate=true;");let s=f.submit_request(&d,owner,None,&loc,&loc).unwrap();let crate::http::Request::FormPost{body,..}=s.request else{panic!("POST")};assert_eq!(body,b"q=");assert_eq!(f.controls.iter().map(|(&n,c)|(n,c.required,c.checked,c.value.text(),c.owner)).collect::<Vec<_>>(),before);}

#[test]
fn form_no_validate_truthiness_is_hook_free_and_named_control_keeps_precedence(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('form'),a=Object.getOwnPropertyDescriptor(HTMLFormElement.prototype,'noValidate'),n=document.getElementById('area'),calls=0,author={toString:function(){calls++;throw 'conversion';},valueOf:function(){calls++;throw 'conversion';}};for(var value of [false,0,-0,NaN,'',null,undefined,BigInt(0)]){a.set.call(x,value);if(x.noValidate!==false||x.hasAttribute('novalidate'))throw 'false value';}for(var value of [true,1,-1,Infinity,'false',[],{},new Boolean(false),Symbol('bool'),BigInt(1),author]){a.set.call(x,value);if(x.noValidate!==true||x.getAttributeNS(null,'novalidate')!==''||calls)throw 'true value';}a.set.call(x);if(x.noValidate!==false||calls)throw 'missing argument';n.setAttribute('name','noValidate');if(x.noValidate!==n)throw 'named mask';a.set.call(x,author);if(x.noValidate!==n||a.get.call(x)!==true||calls)throw 'named saved setter';n.setAttribute('name','q');if(x.noValidate!==true)throw 'live mask';"#);}
#[test]
fn form_no_validate_inert_namespace_raw_attribute_and_independent_copy(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=(new Document()).createElementNS('http://www.w3.org/1999/xhtml','form');x.setAttributeNS('urn:foreign','novalidate','foreign');x.setAttributeNS(null,'NOVALIDATE','upper');if(x.noValidate!==false)throw 'namespace';x.setAttributeNS(null,'novalidate','\ud800');if(x.noValidate!==true)throw 'raw presence';var a=x.getAttributeNodeNS(null,'novalidate'),copy=x.cloneNode(false);copy.noValidate=false;if(copy.noValidate!==false||x.noValidate!==true||a.value!=='\ud800'||copy.getAttributeNS('urn:foreign','novalidate')!=='foreign')throw 'independent copy';x.noValidate=true;if(x.getAttributeNodeNS(null,'novalidate')!==a||a.value!=='')throw 'same native attr';"#);}
#[test]
fn form_no_validate_attribute_producers_observe_presence_and_preserve_dirty_controls(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form'),editor=document.getElementById('area');editor.value='Edited';var a=x.getAttributeNodeNS(null,'novalidate'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true,attributeFilter:['novalidate']});");let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")).unwrap();{let e=&mut f.controls.get_mut(&n).unwrap().value;e.cursor=3;e.anchor=1;e.offset=2;}for source in ["x.setAttribute('novalidate','false');","x.setAttributeNS(null,'novalidate','false');","a.value='false';","a.nodeValue='false';","a.textContent='false';"]{p.begin_job();run(&mut d,&mut f,&mut p,"x.noValidate=true;watch.takeRecords();");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,"var rows=watch.takeRecords();if(x.noValidate!==true||a!==x.getAttributeNodeNS(null,'novalidate')||rows.length!==1||rows[0].oldValue!==''||rows[0].attributeName!=='novalidate'||editor.value!=='Edited')throw 'presence producer';");let c=&f.controls[&n];assert_eq!((c.value.cursor,c.value.anchor,c.value.offset,c.dirty_value,c.required),(3,1,2,true,true));}run(&mut d,&mut f,&mut p,r#"var replacement=document.createAttribute('novalidate');replacement.value='\ud800';x.setAttributeNodeNS(replacement);if(x.noValidate!==true||a.ownerElement!==null||replacement.ownerElement!==x)throw 'raw replacement';x.noValidate=false;if(x.noValidate!==false||replacement.ownerElement!==null)throw 'remove';"#);}
#[test]
fn form_no_validate_brand_and_prototype_authority(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form'),P=HTMLFormElement.prototype,a=Object.getOwnPropertyDescriptor(P,'noValidate');for(var bad of [{},document,document.body,Object.create(P),document.getElementById('area')]){try{a.set.call(bad,true);throw 'missing brand';}catch(e){if(!(e instanceof TypeError))throw e;}}Object.defineProperty(P,'noValidate',{get:function(){return 'author';},configurable:true});a.set.call(x,false);if(x.noValidate!=='author'||a.get.call(x)!==false)throw 'saved authority';delete P.noValidate;if(x.noValidate!==undefined)throw 'deleted';Object.defineProperty(P,'noValidate',a);");}
#[test]
fn form_no_validate_bounded_refusal_is_atomic_and_recovers(){for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form');x.noValidate=false;");let Value::Host(object)=p.runtime.execute("x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("form")};let before=format!("{:?}",d.nodes);let retained=p.state.retained_limit;let capture=(p.state.retained,p.state.dom_commits);p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())};let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.form_no_validate_set(object,&Value::Bool(true));assert!(result.is_err(),"mode {mode}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits),capture);p.state.retained_limit=retained;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"x.noValidate=true;if(x.noValidate!==true)throw 'fresh recovery';");}for expired in [false,true]{let(mut d,mut f,mut p)=fixture();let Value::Host(object)=p.runtime.execute("document.getElementById('form');",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("form")};p.begin_job();if expired{p.state.execution_deadline=Some(Instant::now());}else{p.state.host_work=0;}assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.form_no_validate_get(object).is_err());p.state.execution_deadline=None;p.begin_job();p.state.copy_work=0;assert!(matches!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.form_no_validate_get(object),Ok(Value::Bool(true))));}}

#[test]
fn form_no_validate_saved_child_origin_precedes_conversion_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLFormElement.prototype,'noValidate'),calls=0;if(a.get.call(x)!==true)throw 'same origin';");p.set_location(&crate::navigation::address("https://foreign-form-no-validate.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);for code in ["a.get.call(x);","a.set.call(x,{toString:function(){calls++;return 'on';}});"]{p.begin_job();let error=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);}p.set_location(&crate::navigation::address("https://form-no-validate.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'origin converted';a.set.call(x,'ON');if(x.noValidate!==true)throw 'fresh recovery';");}
